beforeSaveCustomScript:
name = string\trim(string\concatenate(nome, ' ', cognome));

if (cf != null) {
    cf = string\upperCase(string\trim(cf));
}

if (provincia != null) {
    provincia = string\upperCase(string\trim(provincia));
}

$today = datetime\today();
$beforeStart = ifThenElse(dataIngresso == null, false, dataIngresso > $today);
$afterEnd = ifThenElse(dataDimissione == null, false, dataDimissione < $today);
stato = ifThenElse($beforeStart || $afterEnd, 'Inattivo', 'Attivo');
